[gcode_macro M604]
gcode:
    DISABLE_ALL_SENSOR
    {% set mode = params.T|default(0)|int %}
    # q2-load-temp-memory (QIDI_Q2 #26): the material left in the nozzle is pushed out at its own
    # temperature when it is hotter than the new filament (e.g. PETG before PLA). Heating (T0) and
    # the push (T1) use the higher of the two; the flush (T2) runs at the new filament's temperature.
    {% set q2_new = params.S|default(250)|int %}
    {% set q2_old = [printer.save_variables.variables.q2_fila_temp|default(0)|int, 350]|min %}
    {% set q2_hot = [q2_new, q2_old]|max %}
    {% set hotendtemp = q2_new if mode == 2 else q2_hot %}
    {% elif mode ==1 %}      #尝试挤入
        G92 E0
    {% elif mode ==1 %}      #尝试挤入
        {% if q2_hot > q2_new %}
            M118 Old material is pushed out at {q2_hot} C
            M109 S{q2_hot}
        {% endif %}
        G92 E0
        SET_PRINT_SUB_STATUS SUB_STATUS=clean_filamenting
        MOVE_TO_TRASH
        M109 S{hotendtemp}
        SET_PRINT_SUB_STATUS SUB_STATUS=clean_filamenting
        MOVE_TO_TRASH
        {% if q2_hot > q2_new %}
            M104 S{q2_new}
            TEMPERATURE_WAIT SENSOR=extruder MINIMUM={q2_new}
        {% else %}
            M109 S{hotendtemp}
        {% endif %}
        M400
        M106 S0
        M104 S0
        SET_PRINT_MAIN_STATUS MAIN_STATUS=ready
        M400
        M106 S0
        M104 S0
        _REMEMBER_FILA_TEMP SET={q2_new}
        SET_PRINT_MAIN_STATUS MAIN_STATUS=ready
[gcode_macro M603]
description: filament unlode
gcode:
    SET_PRINT_MAIN_STATUS MAIN_STATUS=filament_unload_7
    DISABLE_ALL_SENSOR
    {% set hotendtemp = params.S|default(250)|int %}
[gcode_macro M603]
description: filament unlode
gcode:
    SET_PRINT_MAIN_STATUS MAIN_STATUS=filament_unload_7
    DISABLE_ALL_SENSOR
    # q2-load-temp-memory (QIDI_Q2 #26): unload at the old material's temperature if it is higher
    {% set q2_old = [printer.save_variables.variables.q2_fila_temp|default(0)|int, 350]|min %}
    {% set hotendtemp = [params.S|default(250)|int, q2_old]|max %}
    M118 Unload finish
    _REMEMBER_FILA_TEMP SET={hotendtemp}
    M118 Unload finish
